<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$svc=new AdminOperationsService(Database::connection());$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$id=(int)$_POST['id'];if($_POST['decision']==='approve'){$svc->approveAction($id,(int)auth_user()['id'],$_POST['decision_reason']??'');$success='Action approved and executed.';}else{$svc->rejectAction($id,(int)auth_user()['id'],$_POST['decision_reason']??'');$success='Action rejected.';}}catch(Throwable $e){$error=$e->getMessage();}}$rows=$svc->pendingActions();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Approvals</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>Maker / Checker Approvals</h2><a href="<?=url('admin/')?>">Dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Action</th><th>Entity</th><th>Requester</th><th>Reason</th><th>Created</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['action_type'])?></td><td><?=e($r['entity_type'])?> #<?=e((string)$r['entity_id'])?></td><td><?=e($r['requester_email'])?></td><td><?=e($r['reason'])?></td><td><?=e($r['created_at'])?></td><td><form method="post" class="d-flex gap-2 flex-wrap"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input name="decision_reason" class="form-control form-control-sm" placeholder="Decision reason"><button name="decision" value="approve" class="btn btn-sm btn-success">Approve</button><button name="decision" value="reject" class="btn btn-sm btn-outline-danger">Reject</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></body></html>
